<?php
require_once __DIR__ . '/includes/bootstrap.php';
$pageTitle = 'Browse recipes';
$search = trim((string) ($_GET['q'] ?? ''));
$categoryId = filter_input(INPUT_GET, 'category', FILTER_VALIDATE_INT) ?: null;
$categories = Recipe::categories();
$recipes = Recipe::latest($search, $categoryId, Auth::id());
require __DIR__ . '/includes/header.php';
?>
<section class="container page-section listing-head"><p class="eyebrow">The community shelf</p><h1>Recipes for slow mornings and full tables.</h1><p class="lead">Search by a favorite ingredient, browse by category, or simply see what your neighbors are making.</p><form class="filter-bar" method="get"><label class="search-field"><span>Search</span><input type="search" name="q" value="<?= e($search) ?>" placeholder="Try banana, bread, cookies..."></label><label><span>Category</span><select name="category"><option value="">All categories</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= $categoryId === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><button class="button" type="submit">Find recipes</button></form></section>
<section class="container page-section results-section"><div class="section-heading"><h2><?= count($recipes) ?> recipe<?= count($recipes) === 1 ? '' : 's' ?> found</h2><?php if ($search || $categoryId): ?><a class="text-link" href="<?= BASE_URL ?>/recipes.php">Clear filters</a><?php endif; ?></div><?php if (!$recipes): ?><div class="empty-state"><h3>No recipes matched that search.</h3><p>Try a broader word or share the recipe you had in mind.</p></div><?php else: ?><div class="recipe-grid"><?php foreach ($recipes as $recipe): ?><article class="recipe-card" data-recipe-url="<?= BASE_URL ?>/recipe_view.php?id=<?= (int) $recipe['id'] ?>" tabindex="0" role="link"><div class="recipe-image"><span><?= e(strtoupper(substr($recipe['category_name'], 0, 2))) ?></span></div><div class="recipe-card-body"><div class="card-meta"><span><?= e($recipe['category_name']) ?></span><span><?= date('M j, Y', strtotime($recipe['created_at'])) ?></span></div><h3><a href="<?= BASE_URL ?>/recipe_view.php?id=<?= (int) $recipe['id'] ?>"><?= e($recipe['title']) ?></a></h3><p><?= e($recipe['short_description']) ?></p><div class="card-footer"><small>by <?= e($recipe['author_name']) ?></small><?php if ((int) $recipe['is_favorite']): ?><span class="favorite-mark" title="Saved to favorites">★</span><?php endif; ?></div></div></article><?php endforeach; ?></div><?php endif; ?></section>
<?php require __DIR__ . '/includes/footer.php'; ?>
